      </button>

      <div class="relative w-full h-[calc(100vh-5rem)] bg-off-white">
        <Swiper
          :modules="[Navigation, Pagination]"
          :slides-per-view="1"
          :navigation="{
            nextEl: '.gallery-next',
            prevEl: '.gallery-prev',
          }"
            :pagination="{
            type: 'fraction',
            el: '.gallery-fraction',
            renderFraction: function (currentClass, totalClass) {
              return `<span class='bg-off-white'><span class=\'${currentClass}\'></span> / <span class=\'${totalClass}\'></span></span>`
            },
          }"
          class="h-full"
          :loop="true"
        >
          <SwiperSlide
            v-for="(slide, index) in galleryPage?.images"
            :key="index"
            class="relative"
          >
            <SanityImage
              v-if="slide.image"
              :image="slide.image"
              :alt="slide.title"
              :preserve-aspect-ratio="false"
              loading="lazy"
              class="absolute inset-0 w-full h-full object-contain"
            />

            <!-- Caption -->
            <div
              class="absolute inset-x-0 bottom-0 p-0 flex w-[calc(100%-4rem)]"
            >
              <p class=" text-brown p-4 bg-[#f0efd6c3]">
               <span class="">{{ slide.title }}</span><span v-if="slide.title && slide.caption">:</span> {{ slide.caption }}
              </p>

            </div>
          </SwiperSlide>
        </Swiper>

        <div class="gallery-fraction z-10 left-full! w-auto! fixed right-0! bottom-0 z-10 text-brown! bg-off-white me-12 mb-3 flex! ms-auto! whitespace-nowrap"></div>
      </div>
    </div>
  </main>
</template>

<style>
.swiper-pagination-bullet {
  background: white;
  opacity: 0.5;
}

.swiper-pagination-bullet-active {
  opacity: 1;
}
</style>